contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 supplyAmount, address to, uint256 redeemAmount) public payable {
        require(supplyAmount > 0, "supplyAmount must be > 0");
        require(redeemAmount > 0, "redeemAmount must be > 0");
        require(to != address(0), "to must not be zero");
        require(address(this).balance >= 0, "balance ok");

        // Drive c through public entry points so the redeemer has credits to burn.
        IERC20(c.depositToken()).transferFrom(msg.sender, address(this), supplyAmount);
        IERC20(c.depositToken()).approve(address(c), supplyAmount);
        c.supplyTokenTo(supplyAmount, to);

        // Read before state for the caller (to) and the caller's balance.
        uint256 beforeCredits = c.imBalances(to);
        require(beforeCredits > 0, "caller must have credits");

        uint256 beforeBalance = IERC20(c.depositToken()).balanceOf(to);

        // Perform the deciding call.
        uint256 actualOut = c.redeemToken(redeemAmount);

        uint256 afterCredits = c.imBalances(to);
        uint256 afterBalance = IERC20(c.depositToken()).balanceOf(to);

        // General rule: the credits burned equal the token value change observed,
        // and imBalances decreased by exactly that amount.
        assert(beforeCredits - afterCredits == afterBalance - beforeBalance);
    }

    receive() external payable {}
}

