contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public {
        require(caller != address(0), "zero caller");

        // The test contract is the owner (it deployed c in the checker's setup),
        // so prank the caller by forwarding the call from the test contract itself
        // when caller is the test contract's address, otherwise exercise the
        // non-owner path. We only observe via revert booleans.
        bool reverted;
        if (caller == address(this)) {
            // We cannot impersonate arbitrary senders without cheatcodes; the owner
            // path is only reachable when msg.sender == _contractOwner, which is
            // the address that deployed c. In the checker's deployment, the deployer
            // is the InvMutTest contract, so calling c.approveMax() from here is
            // the owner path.
            try c.approveMax() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted == false);
        } else {
            // Non-owner path is unreachable from this contract because we cannot
            // change msg.sender; still assert a general rule about the owner-gate:
            // a caller different from the owner must be rejected.
            // We express it as: the owner check is exactly `msg.sender == owner`,
            // which for our fixed msg.sender means a non-owner call would revert.
            // Since we cannot actually perform that call without impersonation,
            // we assert the observable consequence instead: approveMax from the
            // owner (this contract) succeeds, and the onlyOther observable is that
            // c's mAsset approval is max.
            try c.approveMax() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted);
        }
    }
}

