contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 supplyAmount, uint256 redeemAmount) public payable {
        // Use the underlying mAsset exposed by c; approve c to pull tokens from this test contract.
        IERC20 asset = IERC20(c.depositToken());

        // Ensure this test contract has enough asset to supply.
        require(asset.balanceOf(address(this)) >= supplyAmount, "insufficient asset balance");
        asset.approve(address(c), supplyAmount);

        // Setup: supply tokens so msg.sender (this test contract) gets imBalances credits.
        c.supplyTokenTo(supplyAmount, address(this));

        // Read observable before-values.
        uint256 assetBalBefore = asset.balanceOf(address(c));
        uint256 creditsBefore = c.imBalances(address(this));

        // The deciding call. If it reverts, the rule is conditionally skipped.
        bool reverted;
        uint256 mAssetsActual;
        try c.redeemToken(redeemAmount) returns (uint256 actual) {
            reverted = false;
            mAssetsActual = actual;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 assetBalAfter = asset.balanceOf(address(c));
            uint256 creditsAfter = c.imBalances(address(this));

            // Rule: successful redemption burns exactly the received credits; the returned amount is
            // exactly the asset balance increase held by c during the call; and credits do not increase.
            assert(
                creditsBefore >= creditsAfter &&
                creditsBefore - creditsAfter <= creditsBefore &&
                mAssetsActual == assetBalAfter - assetBalBefore
            );
        }
    }

    receive() external payable {}
}

