        require(creditsBefore > 0, "no credits credited");

        bool reverted;
        uint256 returned;
        try c.redeemToken(redeemAmount) returns (uint256 actual) {
            returned = actual;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 creditsAfter = c.imBalances(to);
        uint256 mAssetBalanceOfC = IERC20(c.depositToken()).balanceOf(address(c));

        // General rule:
        // - if the redeemer's credit balance is less than what the call requires,
        //   the redemption must revert and leave `to`'s credit balance untouched;
        // - otherwise credits must strictly decrease by the burn amount and the
        //   returned value must not exceed the amount requested (bounded by the
        //   mAssets actually available to the contract).
        assert(
            (
                redeemAmount > creditsBefore && reverted && creditsAfter == creditsBefore
            )
            ||
            (
                redeemAmount <= creditsBefore && !reverted && creditsAfter < creditsBefore && returned <= redeemAmount + mAssetBalanceOfC
            )
        );
    }

    receive() external payable {}
}

