    }

    function run(
        address savingsContract,
        address underlyingToken,
        address targetAccount,
        uint256 supplyAmount
    ) public payable {
        require(savingsContract != address(0), "savings zero");
        require(underlyingToken != address(0), "underlying zero");
        require(address(this).balance >= 0, "balance ok");

        IERC20 underlying = IERC20(underlyingToken);

        IMockSavings mock = IMockSavings(savingsContract);
        mock.setExchangeRate(mock.exchangeRate());
        mock.setUnderlying(underlyingToken);
        mock.setImBalance(address(c), supplyAmount);

        underlying.mint(address(this), supplyAmount);
        underlying.approve(address(c), supplyAmount);

        c.supplyTokenTo(supplyAmount, targetAccount);

        uint256 expectedCredits = underlying.balanceOf(address(c));
        require(expectedCredits <= supplyAmount, "credits <= supply");

        uint256 exchangeRate = mock.exchangeRate();
        uint256 expectedBalance = (expectedCredits * exchangeRate) / 1e18;

        uint256 imBalance = mock.imBalance(address(c));

        try c.balanceOfToken(targetAccount) returns (uint256 returned) {
            assert(returned == (mAssetBalance(underlyingToken) * exchangeRate) / 1e18);
        } catch {
            assert(false);
        }
    }

    function mAssetBalance(address token) internal view returns (uint256) {
        return IERC20(token).balanceOf(address(c));
    }

    receive() external payable {}
}

