contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, address to) public payable {
        require(to != address(0), "invalid recipient");
        require(amount > 0, "amount must be positive");

        // The amount of mAsset must already have been approved to C by msg.sender (this test contract).
        // We approve C to pull the mAsset from us. c.savings() gives the savings contract address,
        // and c.mAsset() gives the mAsset token address. Since we only have the public ABI of C,
        // we call the approved token through the interface already known to grant allowance.
        IERC20 mAsset = c.mAsset();
        mAsset.approve(address(c), amount);

        // Record the before values of the relevant general-rule observables.
        uint256 beforeImBalances = c.imBalances(to);
        uint256 beforeCredits = c.savings().creditBalances(address(c));

        // Drive the public entry point that changes state (must be a top-level call).
        c.supplyTokenTo(amount, to);

        // Read the after values.
        uint256 afterImBalances = c.imBalances(to);
        uint256 afterCredits = c.savings().creditBalances(address(c));

        // General rule: the increase in imBalances[to] equals the increase in credits that
        // the savings contract holds for c, which is exactly the credits issued by depositSavings.
        assert(afterImBalances - beforeImBalances == afterCredits - beforeCredits);
    }

    receive() external payable {}
}

