contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address addr, uint256 amount, address to) public payable {
        // Ensure the address used for balance reads is well-defined (any address is fine,
        // but we compare two reads at different credit levels).
        require(addr != address(0), "zero addr");
        require(to != address(0), "zero to");

        // Read the exchange rate exposed by c's savings contract through the public getter.
        uint256 rate = c.savings().exchangeRate();

        // Snapshot the public mapping entry for addr.
        uint256 beforeCredits = c.imBalances(addr);
        uint256 beforeBalance = c.balanceOfToken(addr);

        // Attempt to change c's internal credit balance for `addr` via supplyTokenTo.
        // This requires the test contract to hold enough mAsset and for the savings
        // depositSavings call to succeed. We do it inside try/catch so the test has a
        // well-defined outcome regardless of token state.
        bool supplyReverted;
        bytes memory supplyData = abi.encodeWithSelector(
            c.supplyTokenTo.selector,
            amount,
            addr
        );
        (bool supplyOk, bytes memory supplyRet) = address(c).call(supplyData);
        supplyReverted = !supplyOk || supplyRet.length != 0;

        // Re-read the public mapping entry and the balance function.
        uint256 afterCredits = c.imBalances(addr);
        uint256 afterBalance = c.balanceOfToken(addr);

        // The general rule: for any address, balanceOfToken(addr) equals the
        // public credit balance times the current exchange rate divided by 1e18.
        // This must hold both before and after any successful supply call.
        assert(
            afterBalance == (afterCredits * rate) / 1e18 &&
                beforeBalance == (beforeCredits * rate) / 1e18
        );
    }

    receive() external payable {}
}

