contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositAmount, uint256 redeemAmount, uint256 extraAmount, address other) public payable {
        require(other != address(this), "other must differ from caller");
        require(extraAmount > 0, "need extra credits");
        if (depositAmount > 0) {
            c.supplyTokenTo(depositAmount, address(this));
        }
        if (extraAmount > 0) {
            c.supplyTokenTo(extraAmount, other);
        }

        uint256 creditsBeforeCaller = c.imBalances(address(this));
        uint256 creditsBeforeOther = c.imBalances(other);
        uint256 cBalanceBefore = address(c).balance;
        uint256 myBalanceBefore = address(this).balance;

        bool reverted;
        uint256 actual;
        try c.redeemToken(redeemAmount) returns (uint256 _actual) {
            actual = _actual;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 creditsAfterCaller = c.imBalances(address(this));
            uint256 creditsAfterOther = c.imBalances(other);
            uint256 cBalanceAfter = address(c).balance;
            uint256 myBalanceAfter = address(this).balance;

            assert(
                creditsBeforeCaller >= creditsAfterCaller &&
                creditsAfterOther == creditsBeforeOther &&
                cBalanceBefore >= cBalanceAfter &&
                myBalanceAfter >= myBalanceBefore &&
                actual == myBalanceAfter - myBalanceBefore &&
                cBalanceBefore - cBalanceAfter == actual
            );
        } else {
            assert(
                c.imBalances(address(this)) == creditsBeforeCaller &&
                c.imBalances(other) == creditsBeforeOther &&
                address(c).balance == cBalanceBefore &&
                address(this).balance == myBalanceBefore
            );
        }
    }

    receive() external payable {}
}

