contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public payable {
        // Only the owner (this test contract, since it deployed c) may succeed.
        // For any other caller, approveMax must revert.
        uint256 allowanceBefore = c.mAsset().allowance(address(c), address(c.savings()));

        // Impersonate the caller by directly checking the precondition.
        // We cannot change msg.sender for a call on c, so we detect
        // whether caller is the owner by comparing it to address(this).
        // If caller is not this contract, approveMax must revert.
        bool reverted;
        if (caller != address(this)) {
            // Force msg.sender to be address(this); cannot simulate arbitrary sender.
            // Instead, we test the owner-only rule through the only sender we control.
            // This branch is unreachable in a single-transaction checker run where
            // msg.sender for calls on c is always this contract.
            reverted = true;
        } else {
            try c.approveMax() { reverted = false; } catch { reverted = true; }
        }

        uint256 allowanceAfter = c.mAsset().allowance(address(c), address(c.savings()));

        // General rule: if approveMax succeeded, the allowance must be max uint256;
        // if it reverted, the allowance must not have decreased.
        assert(!reverted ? allowanceAfter == type(uint256).max : allowanceAfter >= allowanceBefore);
    }

    receive() external payable {}
}

