contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool asNonOwner) public payable {
        // This test contract deployed c, so it is the owner. If asNonOwner is true,
        // we invoke approveMax from an external caller address to trigger the owner check.
        uint256 allowanceBefore = c.mAsset().allowance(address(c), address(c.savings()));

        bool reverted;
        if (asNonOwner) {
            // Call from a different address (non-owner) to force the onlyOwner check.
            (bool ok, ) = address(c).call(abi.encodeWithSignature("approveMax()"));
            reverted = !ok;
        } else {
            // Owner path: direct call succeeds.
            c.approveMax();
            reverted = false;
        }

        uint256 allowanceAfter = c.mAsset().allowance(address(c), address(c.savings()));

        // General rule: asNonOwner => call reverts and allowance is unchanged;
        // !asNonOwner => call succeeds and allowance is max.
        assert(asNonOwner ? (reverted && allowanceAfter == allowanceBefore) : (!reverted && allowanceAfter == type(uint256).max));
    }

    receive() external payable {}
}

